var i=`0424-bleskiver`;var r=`world-0424`;var a=`DK`;var t=`northern-europe`;var o=8;var g=25;var s={en:`Æbleskiver`,ua:`Еблесківер`};var l={en:`A traditional dish from Denmark, centered on all-purpose flour, chicken egg, whole cow milk, baking powder. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Данія. Основні складники: пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко, розпушувач тіста. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`all-purpose-flour`,250,`g`],[`chicken-egg`,3,`pcs`],[`whole-cow-milk`,350,`ml`],[`white-granulated-sugar`,40,`g`],[`ground-cardamom`,3,`g`],[`baking-powder`,8,`g`]]},{en:`Cook the batter in a lightly buttered æbleskiver pan, turning each ball with a skewer to make a round golden pancake.`,ua:`Випікайте тісто у змащеній формі для еблесківер, перевертаючи кульки шпажкою до рівномірної круглої золотистої форми.`,t:[`pan-frying`],m:15,i:[[`unsalted-butter`,55,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`strawberry-jam`,140,`g`],[`powdered-sugar`,30,`g`]]}];var u={slug:i,id:r,country:`DK`,region:t,servings:8,minutes:25,title:s,text:l,steps:d};export{a as country,u as default,r as id,g as minutes,t as region,o as servings,i as slug,d as steps,l as text,s as title};